document.addEventListener('input',e=>{const el=e.target as HTMLInputElement;const input=el.dataset.input;if(input==='day')state.scene.day=Number(el.value);if(input==='time')state.scene.time=Number(el.value);if(input==='latitude')state.scene.lat=Number(el.value);if(input){updateSceneUI();persist();}if(el.dataset.save==='reason'||el.dataset.save==='reflection'){state[el.dataset.save]=el.value;persist();}});
document.addEventListener('change',e=>{const el=e.target as HTMLInputElement;if(el.dataset.motion){preferences.motion=el.value as 'system'|'on'|'off';state.reducedMotion=el.value==='off';writePreferences(preferences);persist();}if(el.dataset.pref==='guidance'||el.dataset.pref==='voice'){preferences[el.dataset.pref]=el.checked;if(el.dataset.pref==='voice'&&!el.checked)stopSpeaking();writePreferences(preferences);if(!preferences.guidance)hideCoach();}for(const [attr,key]of [['revised','revised'],['self','self'],['rubric','rubric']] as const){if(el.dataset[attr]!==undefined){const arr=state[key];const i=Number(el.dataset[attr]);while(arr.length<=i)arr.push(-1);arr[i]=el.value===''?-1:Number(el.value);persist();}}if(el.dataset.setting==='motion'){state.reducedMotion=el.checked;document.documentElement.classList.toggle('reduced-motion',el.checked);persist();}if(el.dataset.setting==='quality'){state.quality=el.value as any;persist();}});
document.addEventListener('keydown',e=>{if(dialog||((e.target as HTMLElement).closest('input,textarea,select,[data-interactive]')))return;if(e.key==='ArrowRight'||e.key==='PageDown'){e.preventDefault();step(1);}if(e.key==='ArrowLeft'||e.key==='PageUp'){e.preventDefault();step(-1);}});
let swipe:{x:number;y:number}|undefined;
document.addEventListener('pointerdown',e=>{if(e.pointerType==='touch'&&!dialog&&!(e.target as HTMLElement).closest('button,a,input,select,textarea,[data-interactive]'))swipe={x:e.clientX,y:e.clientY};});
document.addEventListener('pointerup',e=>{if(!swipe)return;const dx=e.clientX-swipe.x,dy=e.clientY-swipe.y;swipe=undefined;if(Math.abs(dx)>85&&Math.abs(dy)<45)step(dx<0?1:-1);});
document.addEventListener('pointercancel',()=>swipe=undefined);
wide.addEventListener('change',()=>{if(!dialog)render();});
document.addEventListener('visibilitychange',()=>{if(document.hidden)persist();});
window.addEventListener('beforeunload',()=>{persist();stopScene();});

function infoForPage(p:number){return p<=11?(p===9?'tilt':'orbit'):p===13?'distance':p<=13?'seasons':p===15?'latitude':p<=17?'daynight':p===19?'packing':'seasons';}
function pageHook(p:number){const g=guides[p-1];return `<button class="page-hook" data-action="guide:${p}" aria-label="Hướng dẫn trang ${p}: ${esc(g.hook)}">${img(g.icon,'','')}<span><small>CÂU HỎI DẪN ĐƯỜNG</small><strong>${g.hook}</strong></span>${img('A03','hook-help','')}</button>`;}
const pageMedia:Record<number,{info?:string;video?:boolean}>={8:{info:'orbit'},9:{info:'tilt'},10:{video:true},12:{info:'seasons'},13:{info:'distance',video:true},14:{info:'daynight'},15:{info:'latitude'},17:{info:'daynight'},19:{info:'packing'},24:{video:true}};
function pageTools(p:number){const m=pageMedia[p];return m?`<nav class="page-tools" aria-label="Học liệu trang ${p}">${m.info?btn(img('F03','','')+'Infographic',`info:${m.info}`,'tool-tile'):''}${m.video?btn(img('F06','','')+'Video & nguồn','resources','tool-tile'):''}</nav>`:'';}

function hideCoach(){document.querySelector('#learning-coach')?.setAttribute('hidden','');document.querySelectorAll('.coach-target').forEach(el=>el.classList.remove('coach-target'));}
function armGuide(){if(idle)clearTimeout(idle);if(!preferences.guidance)return;idle=setTimeout(()=>{if(document.hidden||dialog||isTurning()||lastNudge===currentGuide)return;showGuide(currentGuide);lastNudge=currentGuide;},12000);}
function showGuide(p:number){const g=guides[p-1];if(!g)return;currentGuide=p;const coach=document.querySelector<HTMLElement>('#learning-coach');if(!coach)return;hideCoach();coach.hidden=false;coach.setAttribute('role','status');coach.setAttribute('aria-live','polite');coach.innerHTML=`${img('A02','coach-mascot','Sao Mai hướng dẫn')}<div class="coach-copy"><span>SAO MAI · TRANG ${p}</span><h3>${g.hook}</h3><p><b>Em làm:</b> ${g.task}</p><p><b>Để hiểu:</b> ${g.learn}</p><div class="button-row">${btn(g.cta,g.action,'primary')}${btn('Nghe hướng dẫn','read-guide','secondary')}</div></div>${btn('×','guide-close','coach-close','aria-label="Đóng hướng dẫn"')}`;const target=document.querySelector<HTMLElement>(`[data-page="${p}"] [data-action="${g.action}"]`);target?.classList.add('coach-target');if(preferences.voice)readGuide(p);}
function readGuide(p:number){if(!preferences.sound){notify('Âm thanh đang tắt. Bật âm thanh trên thanh công cụ để nghe.');return;}const g=guides[p-1];if(!speak(g.hook+' Em làm: '+g.task+' Để hiểu: '+g.learn))notify('Thiết bị chưa có giọng tiếng Việt. Em có thể đọc lời hướng dẫn trên trang.');}
function readPage(p:number){if(!preferences.sound){notify('Âm thanh đang tắt. Bật âm thanh trên thanh công cụ để nghe.');return;}const page=document.querySelector(`[data-page="${p}"]`);const paragraphs=Array.from(page?.querySelectorAll('.page-body p')||[]).map(el=>el.textContent||'').join(' ');if(!speak(pages[p-1].title+'. '+pages[p-1].intro+' '+guides[p-1].task+' '+paragraphs))notify('Thiết bị chưa có giọng tiếng Việt. Lời dẫn vẫn hiển thị đầy đủ trên trang.');}
function showResources(all=false){const selected=all?resources:resources.filter(r=>r.pages.includes(currentGuide));const visible=selected.length?selected:resources;openDialog('Thư viện học liệu',`<p>Chọn video, tài liệu tham khảo hoặc bài luyện thêm. Video chỉ kết nối YouTube sau khi em chọn phát.</p><div class="resource-cards">${visible.map(r=>`<button data-action="resource:${esc(r.id)}"><img src="${base}assets/${r.type==='youtube'?'F06':'F05'}.webp" alt=""><span><small>${r.type==='youtube'?'VIDEO NHÚNG':'MỞ TÀI LIỆU'}</small><strong>${esc(r.title)}</strong><em>${esc(r.source)}</em></span>${arrow}</button>`).join('')}</div>${!all?btn('Xem tất cả học liệu','resources-all','text-button'):''}<p class="caption">Video, bài đọc và bài luyện thêm được chọn lọc. Những nguồn tiếng Anh được ghi rõ.</p>`);}
function openResource(id:string,embed:boolean){const r=resources.find(r=>r.id===id);if(!r)return;const url=safeResourceURL(r.url);if(!url){announce('Liên kết chưa hợp lệ.');return;}const videoId=youtubeId(r.url);const player=r.type==='youtube'&&videoId?(embed?`<iframe class="youtube-player" title="${esc(r.title)}" src="${embedURL(videoId)}" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe>`:`<div class="youtube-poster">${img('F06','','')}<h3>${esc(r.title)}</h3>${btn('Phát video trong sách',`embed:${r.id}`,'primary')}</div>`):'';openDialog(r.title,`${player}<p class="resource-source">${esc(r.source)}</p><p>${esc(r.description)}</p>${r.type==='youtube'?'<div class="paper-box"><strong>Câu hỏi khi xem</strong><p>Trục Trái Đất có đổi hướng không? Góc chiếu và thời gian chiếu sáng thay đổi thế nào ở hai bán cầu?</p><strong>Chốt bằng tiếng Việt</strong><p>Do trục nghiêng và giữ hướng, hai bán cầu luân phiên ngả về Mặt Trời. Mùa không chủ yếu do khoảng cách gần–xa.</p></div>':''}<a class="primary" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${r.type==='youtube'?'Mở YouTube nếu video bị chặn':'Mở tài liệu ở tab mới'} ↗</a>`,'resource-dialog');}


const panels:Record<number,number>={};
function fitPages(){document.querySelectorAll<HTMLElement>('.book-stage .page').forEach(page=>{const body=page.querySelector<HTMLElement>('.page-body');if(!body||page.classList.contains('cover'))return;const available=body.clientHeight-42;if(available<80)return;body.querySelectorAll<HTMLElement>('.goal-list,.map-list,.instruction-grid').forEach(list=>{if(list.getBoundingClientRect().height<=available)return;const fragment=document.createDocumentFragment();for(const item of Array.from(list.children)){const wrapper=document.createElement('div');wrapper.className=list.className;wrapper.style.margin='0';wrapper.style.gridTemplateColumns='1fr';wrapper.append(item);fragment.append(wrapper);}list.replaceWith(fragment);});const nodes=Array.from(body.children) as HTMLElement[];let groups:HTMLElement[][]=[[]],used=0;for(const node of nodes){const h=node.getBoundingClientRect().height+12;if(used+h>available&&groups.at(-1)!.length){groups.push([]);used=0;}groups.at(-1)!.push(node);used+=h;}if(groups.length<=1)return;const number=Number(page.dataset.page),active=Math.min(panels[number]||0,groups.length-1);nodes.forEach(n=>n.hidden=!groups[active].includes(n));const nav=document.createElement('div');nav.className='within-page';nav.innerHTML=`${active>0?btn('Bước trước',`panel-prev:${number}`):''}<span>Bước ${active+1}/${groups.length}</span>${active<groups.length-1?btn('Tiếp tục',`panel-next:${number}`):''}`;body.append(nav);});}
window.addEventListener('resize',()=>{if(!dialog)render();});

